import { XdrError } from './error.js';

export function paddingLength(length: number): number {
  return (4 - (length % 4)) % 4;
}

export function isPlainObject(
  value: unknown
): value is Record<string, unknown> {
  if (typeof value !== 'object' || value === null) {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

export function assertLength(value: number, name: string): void {
  if (!Number.isInteger(value) || value < 0 || value > 4294967295) {
    throw new XdrError(`${name}: expected uint32 length`);
  }
}

export function assertIntRange(
  value: unknown,
  min: number,
  max: number,
  path: string
): asserts value is number {
  if (
    typeof value !== 'number' ||
    !Number.isInteger(value) ||
    value < min ||
    value > max
  ) {
    throw new XdrError(`${path}: expected integer in range ${min}..${max}`);
  }
}

export function assertBigIntRange(
  value: unknown,
  min: bigint,
  max: bigint,
  path: string
): asserts value is bigint {
  if (typeof value !== 'bigint' || value < min || value > max) {
    throw new XdrError(`${path}: expected bigint in range ${min}..${max}`);
  }
}

export function assertNumber(
  value: unknown,
  path: string
): asserts value is number {
  if (typeof value !== 'number') {
    throw new XdrError(`${path}: expected number`);
  }
}

export function assertUint8Array(
  value: unknown,
  path: string
): asserts value is Uint8Array {
  if (!(value instanceof Uint8Array)) {
    throw new XdrError(`${path}: expected Uint8Array`);
  }
  // Check if the Uint8Array is detached or out of bounds by attempting to access an element.
  try {
    Uint8Array.prototype.at.call(value, 0);
  } catch {
    throw new XdrError(`${path}: Uint8Array is detached or out of bounds`);
  }
}

export function assertArray(
  value: unknown,
  path: string
): asserts value is unknown[] {
  if (!Array.isArray(value)) {
    throw new XdrError(`${path}: expected array`);
  }
}
